const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto'),png=require('./png.cjs');const{createCanvas,ImageData}=require('C:/Users/Administrator/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/@napi-rs/canvas');
(async()=>{let url='http://127.0.0.1:8765/api/project?id=test-town-body02-idle-walk-20261031',r=await fetch(url),raw=await r.text(),p=JSON.parse(raw),c=structuredClone(p),etag=r.headers.get('etag'),out=path.resolve('备份/20261031-测试人物准确沿用旧肤色阴影-'+Date.now());fs.mkdirSync(out,{recursive:true});fs.writeFileSync(out+'/before.json',raw);fs.writeFileSync(out+'/metadata.json',JSON.stringify({etag,sha256:crypto.createHash('sha256').update(raw).digest('hex')}));let map={e8cbbb:'e0c5b4',dcb2a3:'e0c5b4',fff5ec:'feede1'},count=0;function change(url){let a=png.decode(Buffer.from(url.split(',')[1],'base64')),d=new Uint8ClampedArray(a.data);for(let i=0;i<d.length;i+=4){let k=Buffer.from(d.slice(i,i+3)).toString('hex');if(d[i+3]&&map[k]){d.set(Buffer.from(map[k],'hex'),i);count++;}else assert.deepEqual([...d.slice(i,i+4)],[...a.data.slice(i,i+4)]);assert.equal(d[i+3],a.data[i+3]);}let cv=createCanvas(a.width,a.height);cv.getContext('2d').putImageData(new ImageData(d,a.width,a.height),0,0);return cv.toDataURL()}
for(let [i,l]of c.layers.entries()){if(l.name==='身体 / 原素材完整帧'||l.name.startsWith('五官底稿'))for(let f of Object.values(l.frameData||{}))f.dataURL=change(f.dataURL);else assert.deepEqual(l,p.layers[i]);}for(let s of c.spriteSheets)if(s.imageDataURL)s.imageDataURL=change(s.imageDataURL);assert(count>0);fs.writeFileSync(out+'/candidate.json',JSON.stringify(c));let check=await fetch(url);assert.equal(check.headers.get('etag'),etag);let put=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json','X-Pixel-Editor':'1','If-Match':etag},body:JSON.stringify(c)}),reply=await put.text();assert.equal(put.status,200,reply);let back=await(await fetch(url)).text();assert.deepEqual(JSON.parse(back),c);fs.writeFileSync(out+'/api-readback.json',back);fs.writeFileSync(out+'/verification.json',JSON.stringify({map,changedPixelsIncludingAtlases:count,otherPixelsAndAlphaUnchanged:true,eyeLayersUnchanged:true,status:put.status},null,2));console.log('Saved 200, readback exact; '+count+' changed pixels including atlas copies. '+out)})().catch(e=>{console.error(e);process.exitCode=1});
